/* ============================================================
   SHARED NAV + FOOTER — Maison de la Verrière
   High Gothic, bold variant
   ============================================================ */

/* ---------- HEADER / NAV ---------- */

.site-nav {
  position: relative;
  background-color: var(--surface);
  color: var(--text);
  padding: 1.4rem 1rem 0;
  border-bottom: 1px solid var(--ornament);
  text-align: center;
  font-family: "Crimson Pro", Georgia, serif;
}

.site-nav::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("svg/quatrefoil-in-square.svg");
  background-size: 80px 80px;
  background-repeat: repeat;
  opacity: 0.06;
  pointer-events: none;
}

.site-nav > * {
  position: relative;
  z-index: 1;
}

.nav-kicker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  font-family: "Cinzel Decorative", serif;
  font-size: 0.7rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 1.2rem;
}

.kicker-rule {
  flex: 0 0 4rem;
  height: 1px;
  background: linear-gradient(
    to right,
    transparent,
    var(--ornament),
    transparent
  );
}

.nav-wordmark {
  margin-bottom: 1.4rem;
}

.wordmark-link {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
  text-decoration: none;
  color: var(--text);
}

.wordmark-line-1 {
  font-family: "Cinzel Decorative", serif;
  font-size: 1.05rem;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--text);
  padding-left: 0.4em;
}

.wordmark-line-2 {
  font-family: "Cinzel Decorative", serif;
  font-weight: 900;
  font-size: 2.6rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary);
  line-height: 1;
  text-shadow: 0 0 18px rgba(201, 162, 58, 0.25);
}

.wordmark-line-3 {
  font-family: "Crimson Pro", serif;
  font-style: italic;
  font-size: 0.85rem;
  letter-spacing: 0.2em;
  color: var(--text);
  opacity: 0.75;
  margin-top: 0.4rem;
}

.nav-arcade {
  padding: 0.5rem 0 1.2rem;
}

.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0;
}

.nav-list li {
  position: relative;
  padding: 0 1.4rem;
}

.nav-list li + li::before {
  content: "✠";
  position: absolute;
  left: -0.4em;
  top: 50%;
  transform: translateY(-50%);
  color: var(--ornament);
  font-size: 0.7rem;
  opacity: 0.6;
}

.nav-link {
  font-family: "Cinzel Decorative", serif;
  font-size: 0.82rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--text);
  text-decoration: none;
  padding: 0.5rem 0;
  display: inline-block;
  border-bottom: 1px solid transparent;
  transition: color 0.3s ease, border-color 0.3s ease;
}

.nav-link:hover,
.nav-link:focus {
  color: var(--primary);
  border-bottom-color: var(--primary);
  outline: none;
}

.nav-divider {
  height: 14px;
  background-image:
    radial-gradient(
      circle at 50% 0,
      var(--ornament) 0,
      var(--ornament) 2px,
      transparent 2.5px
    );
  background-size: 24px 14px;
  background-repeat: repeat-x;
  border-top: 1px solid var(--ornament);
  border-bottom: 1px solid var(--ornament);
  background-color: var(--surface);
}

/* ---------- FOOTER ---------- */

.site-footer {
  position: relative;
  margin-top: 6rem;
  background-color: var(--surface);
  color: var(--text);
  font-family: "Crimson Pro", Georgia, serif;
  border-top: 1px solid var(--ornament);
}

.site-footer::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("svg/quatrefoil-in-square.svg");
  background-size: 80px 80px;
  background-repeat: repeat;
  opacity: 0.05;
  pointer-events: none;
}

.site-footer > * {
  position: relative;
  z-index: 1;
}

/* miniature pointed-arch arcade */
.footer-arcade {
  display: flex;
  justify-content: center;
  gap: 0;
  padding: 1.2rem 0 0;
  background-color: var(--bg);
  border-bottom: 1px solid var(--ornament);
}

.footer-arch {
  display: inline-block;
  width: 44px;
  height: 64px;
  background-color: var(--surface);
  -webkit-mask-image: url("svg/arch-pointed.svg");
          mask-image: url("svg/arch-pointed.svg");
  -webkit-mask-size: contain;
          mask-size: contain;
  -webkit-mask-repeat: no-repeat;
          mask-repeat: no-repeat;
  -webkit-mask-position: center bottom;
          mask-position: center bottom;
  background-color: var(--primary);
  margin: 0 4px;
  opacity: 0.85;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2.5rem;
  max-width: 1100px;
  margin: 0 auto;
  padding: 3rem 2rem 2rem;
}

.footer-col {
  text-align: left;
}

.footer-heading {
  font-family: "Cinzel Decorative", serif;
  font-size: 0.78rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--primary);
  margin: 0 0 1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid rgba(201, 162, 58, 0.4);
}

.footer-text {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text);
  margin: 0;
}

.footer-faint {
  display: inline-block;
  margin-top: 0.3rem;
  font-style: italic;
  font-size: 0.88rem;
  color: var(--text);
  opacity: 0.65;
}

.footer-nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.footer-nav-list li {
  margin-bottom: 0.45rem;
}

.footer-nav-list a {
  font-family: "Crimson Pro", serif;
  font-size: 1rem;
  color: var(--text);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: color 0.3s ease, border-color 0.3s ease;
}

.footer-nav-list a::before {
  content: "⚜  ";
  color: var(--ornament);
  font-size: 0.8em;
  opacity: 0.7;
}

.footer-nav-list a:hover,
.footer-nav-list a:focus {
  color: var(--primary);
  border-bottom-color: var(--primary);
  outline: none;
}

.footer-seal {
  text-align: center;
  padding: 1rem 0 0.5rem;
}

.seal-fleur {
  display: inline-block;
  font-size: 2.4rem;
  color: var(--primary);
  line-height: 1;
}

.footer-colophon {
  text-align: center;
  padding: 1rem 1.5rem 2.4rem;
  font-family: "Crimson Pro", serif;
  font-style: italic;
  font-size: 0.85rem;
  color: var(--text);
  opacity: 0.7;
  letter-spacing: 0.04em;
  border-top: 1px solid rgba(201, 162, 58, 0.25);
  margin: 0 2rem;
}

.colophon-mark {
  color: var(--ornament);
  margin: 0 0.6em;
  opacity: 0.85;
}

/* ---------- responsive ---------- */

@media (max-width: 720px) {
  .wordmark-line-2 { font-size: 2rem; }
  .wordmark-line-1 { font-size: 0.9rem; letter-spacing: 0.3em; }
  .nav-list li { padding: 0 0.7rem; }
  .nav-link { font-size: 0.72rem; letter-spacing: 0.2em; }
  .kicker-rule { flex-basis: 1.5rem; }
  .nav-kicker { font-size: 0.62rem; letter-spacing: 0.22em; }
  .footer-arch { width: 28px; height: 42px; }
  .footer-grid { padding: 2rem 1.4rem 1.4rem; gap: 1.8rem; }
}
